# read_token.py
import base64
import json
import sys

sys.stdout.reconfigure(encoding="utf-8")

token = "eyJhbGciOiJFUzI1NiIsImtpZCI6IjMyYjFmNjI5LWFlM2MtNGM0My1hMWQ4LWJkNDMzNGMzNmQzZCIsInR5cCI6IkpXVCJ9..7rsysNzroBV0nH6YHeYv67Ud7cDMIG68q6tgreX96h6DyK9QjsD7dCRR1MgrZAEYhZW8uXLnX4g7HYCXOk3chA"

payload = token.split(".")[1]
payload += "=" * (-len(payload) % 4)   # base64 는 길이가 4의 배수여야 한다

print(json.dumps(json.loads(base64.urlsafe_b64decode(payload)), indent=2, ensure_ascii=False))